using System;using System.IO;using System.Collections.Generic;using System.Linq;using Game.Runtime;using Game.Components;using Game.Skirmish.Contracts;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
internal static class SourceSimulationProgram {
 static string Input(JObject run,string name){var row=run[name] as JObject??throw new InvalidOperationException("Required input descriptor: "+name);string path=Path.GetFullPath((string)row["path"]??throw new InvalidOperationException("Input path: "+name));string expected=(string)row["sha256"];if(expected==null||expected.Length!=64||AutonomousWorld.Hash(File.ReadAllBytes(path))!=expected)throw new InvalidOperationException("Input hash mismatch: "+name);return path;}
 static int Main(string[] args){try{if(SourceNavigationFactsTool.TryRun(args,out int preparationResult))return preparationResult;if(args.Length!=1)throw new ArgumentException("One explicit SourceSimulationRun request required");var run=JObject.Parse(File.ReadAllText(args[0]));if((int?)run["schema_version"]!=1||(string)run["kind"]!="SkirmishSourceSimulationRun"||(string)run["mission"]!="S002"||(int?)run["seed"]!=104731)throw new InvalidOperationException("Unsupported source simulation profile");string dir=Path.GetFullPath((string)run["output_directory"]),config=Input(run,"runtime_config");if(!Directory.Exists(dir))throw new InvalidOperationException("Prepared isolated output directory required");Input(run,"mission_scene");Input(run,"camera_profile");var before=SourceRuntimeManifest.Write(dir,"before-world",config);int code;SourceNavigationFacts.InputAuditDirectory=dir;try{code=Run(run);}catch(Exception error){Console.Error.WriteLine(error);code=1;}SourceNavigationFacts.VerifyConsumedInputsAfterRun();var after=SourceRuntimeManifest.Write(dir,"after-outcome",config);SourceRuntimeManifest.RequireUnchanged(before,after);return code;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}

 static int Run(JObject run){var dir=Path.GetFullPath((string)run["output_directory"]);using var trace=new StreamWriter(Path.Combine(dir,"aria-trace.jsonl"));using var rawValidator=new StreamWriter(Path.Combine(dir,"validator-state.jsonl"));AutonomousWorld world=null;var load=System.Diagnostics.Stopwatch.StartNew();try{
  SourceOwnerOrderAdmission.RequirePlan();world=new AutonomousWorld();var initialization=Input(run,"initialization");var sha=(string)run["initialization"]["sha256"];world.Initialize(initialization,sha,1f/60);
  string metadata=Input(run,"unit_metadata"),metadataSha=(string)run["unit_metadata"]["sha256"],repo=Path.GetFullPath((string)run["repository_root"]);
  world.BindActualUnitMetadata(metadata,metadataSha,Path.GetFullPath((string)run["source_repository_root"]));
  var transport=new GeneratedS002TransportInputs(world.ActualUnitMetadata,repo);world.PrepareActualProductionInputs(25,0x12345678u,transport.TryMetadata);
  var camera=SourceS002NumericCameraProvider.CreateGenerated(world.Setup,world.ActualDefinition,world.Entities.GetComponentData<GridConfig>(world.GridEntity),initialization,sha,repo);
  var clearance=new GeneratedS002DropClearance(Input(run,"static_clearance"),(string)run["static_clearance"]["sha256"]);
  world.ActualDeliveryOwner.Helicopters=new SourceHelicopterDelivery(world.ActualDeliveryOwner,transport.Templates,()=>camera.Right,()=>camera.Forward,clearance.Reserve);
  if(camera.ProfileSha256!=(string)run["camera_profile"]["sha256"])throw new InvalidOperationException("Current camera profile changed after preworld admission");string scene=Input(run,"mission_scene");world.BindSourceNumericCamera(camera,scene,(string)run["mission_scene"]["sha256"],1280,720,Input(run,"camera_values"),(string)run["camera_values"]["sha256"],Input(run,"camera_motion"),(string)run["camera_motion"]["sha256"]);
  world.BindActualPaidCatalog(metadata,metadataSha);world.InitializeActualBuildingLifetime(repo);world.InitializeActualContinuationOwners();for(int i=0;i<3;i++)world.AdvanceConstructedSourceOwners();world.InitializeSourceS002Aria(world.ActualAriaPaid);
  Console.WriteLine("[ActualS002AutonomousStart] actors=52 buildings=18 navigation=4954 templates=12 fresh=True source_aria=True same_world_paid=True roster_overlays="+world.ObservedRosterOverlayCount+" structure_attackers="+world.ObservedStructureAttackCount+" deadline_seconds="+world.Setup.DeadlineSeconds+" startup_wall_seconds="+load.Elapsed.TotalSeconds);
  var validator=new SourceMissionValidatorSnapshot(world);rawValidator.WriteLine(validator.Capture().ToString(Formatting.None));rawValidator.Flush();double validatorWall=0;int authoredBound=Math.Min(72000,(int)Math.Ceiling((world.Setup.DeadlineSeconds+30d)/world.FixedDeltaTime));int maxTicks=run["max_ticks"]!=null?Math.Min((int)run["max_ticks"],authoredBound):authoredBound;if(maxTicks<=0||maxTicks>72000)throw new ArgumentOutOfRangeException("maxTicks");var phaseTotals=new Dictionary<string,double>();var ariaTotals=new Dictionary<string,double>();double traceWall=0;double start=world.SimulationSeconds;var wall=System.Diagnostics.Stopwatch.StartNew();string status="BoundedPrefix",outcome="None";
  for(int i=0;i<maxTicks;i++){
   camera.AdvanceSourceUnscaledTime(UnityEngine.Time.unscaledTime);var phaseRow=world.AdvanceConstructedSourceOwners();foreach(var v in ((JObject)phaseRow["phase_wall_seconds"]).Properties())phaseTotals[v.Name]=(phaseTotals.TryGetValue(v.Name,out var total)?total:0)+(double)v.Value;var terminalBeforeAria=world.Entities.GetComponentData<SkirmishObjectiveStateComponent>(world.Session);if(terminalBeforeAria.Outcome!=SkirmishOutcomeKind.None){status="SourceTerminal";outcome=terminalBeforeAria.Outcome.ToString();var terminalRaw=validator.Capture();rawValidator.WriteLine(terminalRaw.ToString(Formatting.None));rawValidator.Flush();File.WriteAllText(Path.Combine(dir,"source-terminal.json"),new JObject{["kind"]="OriginalSourceTerminalObservation",["world_id"]=world.WorldId,["tick"]=world.Tick,["simulation_seconds"]=world.SimulationSeconds,["source_outcome"]=outcome,["session_outcome_facts"]=terminalRaw["session_outcome_facts"].DeepClone(),["aria_terminal_step_executed"]=false,["reason"]="Observe source terminal before active-only catalog/policy reads; no synthetic terminal input"}.ToString(Formatting.Indented));break;}var row=world.StepSourceS002Aria();foreach(var v in ((JObject)row["aria_profile_seconds"]).Properties())ariaTotals[v.Name]=(ariaTotals.TryGetValue(v.Name,out var value)?value:0)+(double)v.Value;var traceClock=System.Diagnostics.Stopwatch.StartNew();trace.WriteLine(row.ToString(Formatting.None));traceWall+=traceClock.Elapsed.TotalSeconds;
   if(i%60==0){var diagnosticClock=System.Diagnostics.Stopwatch.StartNew();rawValidator.WriteLine(validator.Capture().ToString(Formatting.None));rawValidator.Flush();validatorWall+=diagnosticClock.Elapsed.TotalSeconds;trace.Flush();File.WriteAllText(Path.Combine(dir,"progress.json"),new JObject{["tick"]=world.Tick,["simulation_seconds"]=world.SimulationSeconds,["wall_seconds"]=wall.Elapsed.TotalSeconds,["last_aria"]=row}.ToString(Formatting.Indented));}
   var objective=world.Entities.GetComponentData<SkirmishObjectiveStateComponent>(world.Session);if(objective.Outcome!=SkirmishOutcomeKind.None){status="SourceTerminal";outcome=objective.Outcome.ToString();break;}
   if((bool?)row["stopped"]==true){status="SourceAriaStopped";break;}
  }
  rawValidator.WriteLine(validator.Capture().ToString(Formatting.None));rawValidator.Flush();var result=new JObject{["status"]=status,["source_outcome"]=outcome,["tick"]=world.Tick,["simulation_seconds"]=world.SimulationSeconds-start,["advance_wall_seconds"]=wall.Elapsed.TotalSeconds,["speed_ratio"]=(world.SimulationSeconds-start)/wall.Elapsed.TotalSeconds,["actual_delivered_members"]=world.ActualDeliveryOwner.DeliveredMembers,["source_reservations"]=JArray.FromObject(world.Entities.GetBuffer<SkirmishProductionReservation>(world.Session,true).ToArray()),["source_produced_units"]=world.Entities.HasBuffer<BuildingProducedUnitReadModel>(world.Boundary)?JArray.FromObject(world.Entities.GetBuffer<BuildingProducedUnitReadModel>(world.Boundary,true).ToArray()):new JArray(),["cumulative_owner_wall_seconds"]=JObject.FromObject(phaseTotals),["cumulative_aria_wall_seconds"]=JObject.FromObject(ariaTotals),["trace_serialization_io_wall_seconds"]=traceWall,["validator_snapshot_wall_seconds"]=validatorWall,["native_order_admission"]=new JObject{["compiled_current_metadata"]=true,["transitive_edges"]=true,["order_first_last"]=true,["declared_owner_sequence"]=JArray.FromObject(SourceOwnerOrderAdmission.DeclaredOrder),["native_observed_total_order"]=false},["full_mission_ready"]=false,["scope"]="ActualGeneratedS002_LogicalPublicData_Diagnostic"};File.WriteAllText(Path.Combine(dir,"result.json"),result.ToString(Formatting.Indented));Console.WriteLine("[ActualS002AutonomousAttempt] "+result.ToString(Formatting.None));return status=="SourceAriaStopped"?2:0;
 }catch(Exception e){var error=new JObject{["status"]="Failed",["tick"]=world?.Tick,["simulation_seconds"]=world?.SimulationSeconds,["error_type"]=e.GetType().FullName,["error"]=e.ToString(),["full_mission_ready"]=false};if(world!=null&&world.Entities.HasComponent<SkirmishObjectiveStateComponent>(world.Session)){error["actual_source_objective"]=JObject.FromObject(world.Entities.GetComponentData<SkirmishObjectiveStateComponent>(world.Session));error["actual_source_match"]=JObject.FromObject(world.Entities.GetComponentData<SkirmishMatchState>(world.Session));try{var failureRaw=new SourceMissionValidatorSnapshot(world).Capture();File.WriteAllText(Path.Combine(dir,"failure-validator-state.json"),failureRaw.ToString(Formatting.Indented));}catch(Exception diagnostic){error["validator_failure"]=diagnostic.Message;}}File.WriteAllText(Path.Combine(dir,"result.json"),error.ToString(Formatting.Indented));Console.Error.WriteLine(error.ToString(Formatting.None));return 1;}}
}
